INSERT OR IGNORE INTO site_settings(key,value_json,updated_at) VALUES ('navigation','{"version":1,"topbar":{"enabled":true,"tagline":"Môi trường · Cộng đồng · Phát triển bền vững","email":"xanh@skyfirst.io.vn","hours":"","phone":"0924 910 210","address":""},"brand_name":"XANH SKY FIRST","brand_description":"Môi trường · Cộng đồng · Công nghệ xanh","logo_url":"/assets/xanh-sky-first-logo.png","cta_label":"Cùng hành động","cta_href":"/tham-gia","search_enabled":true,"items":[{"id":"gioi-thieu","label":"Giới thiệu","href":"/gioi-thieu","visible":true,"children":[{"id":"nguyen-tac","label":"Bốn nguyên tắc hành động","href":"/noi-dung/gioi-thieu-nguyen-tac","visible":true},{"id":"linh-vuc","label":"Năm lĩnh vực hành động","href":"/noi-dung/gioi-thieu-linh-vuc","visible":true}]},{"id":"du-an","label":"Dự án","href":"/du-an","visible":true,"children":[{"id":"dinh-huong-du-an","label":"Định hướng dự án","href":"/noi-dung/du-an-dinh-huong","visible":true},{"id":"sang-kien-xanh","label":"Sáng kiến xanh","href":"/noi-dung/du-an-sang-kien","visible":true}]},{"id":"hoat-dong","label":"Hoạt động","href":"/hoat-dong","visible":true,"children":[{"id":"lich-hoat-dong","label":"Lịch hoạt động","href":"/noi-dung/hoat-dong-lich","visible":true},{"id":"huong-dan-tham-gia","label":"Hướng dẫn tham gia","href":"/noi-dung/hoat-dong-huong-dan","visible":true}]},{"id":"con-nguoi","label":"Con người","href":"/con-nguoi","visible":true,"children":[{"id":"vai-tro","label":"Vai trò & phối hợp","href":"/noi-dung/con-nguoi-vai-tro","visible":true},{"id":"quyen-rieng-tu","label":"Thông tin & quyền riêng tư","href":"/noi-dung/con-nguoi-quyen-rieng-tu","visible":true}]},{"id":"co-hoi","label":"Cơ hội","href":"/co-hoi","visible":true,"children":[{"id":"tinh-nguyen","label":"Cơ hội tình nguyện","href":"/noi-dung/co-hoi-tinh-nguyen","visible":true},{"id":"chuyen-mon","label":"Đóng góp chuyên môn","href":"/noi-dung/co-hoi-chuyen-mon","visible":true}]},{"id":"tai-nguyen","label":"Tài nguyên","href":"/tai-nguyen","visible":true,"children":[{"id":"giao-duc-moi-truong","label":"Giáo dục môi trường","href":"/noi-dung/tai-nguyen-giao-duc","visible":true},{"id":"song-xanh","label":"Lối sống bền vững","href":"/noi-dung/tai-nguyen-song-xanh","visible":true}]},{"id":"tin-tuc","label":"Tin tức","href":"/tin-tuc","visible":true,"children":[{"id":"tieu-chuan-bien-tap","label":"Biên tập & xác minh","href":"/noi-dung/tin-tuc-quy-chuan","visible":true}]},{"id":"tham-gia","label":"Tham gia","href":"/tham-gia","visible":true,"children":[{"id":"quy-trinh-dang-ky","label":"Quy trình đăng ký","href":"/noi-dung/tham-gia-quy-trinh","visible":true},{"id":"cau-hoi-tham-gia","label":"Câu hỏi thường gặp","href":"/noi-dung/tham-gia-cau-hoi","visible":true}]},{"id":"tra-cuu","label":"Tra cứu","href":"/tra-cuu","visible":true,"children":[{"id":"ma-ho-so","label":"Mã hồ sơ & trạng thái","href":"/noi-dung/tra-cuu-ma-ho-so","visible":true}]}],"footer_columns":[{"title":"Khám phá","items":[{"label":"Về Xanh","href":"/gioi-thieu"},{"label":"Con người","href":"/con-nguoi"},{"label":"Dự án","href":"/du-an"},{"label":"Hoạt động","href":"/hoat-dong"},{"label":"Tin tức","href":"/tin-tuc"}]},{"title":"Cùng hành động","items":[{"label":"Đăng ký tham gia","href":"/tham-gia"},{"label":"Cơ hội","href":"/co-hoi"},{"label":"Sáng kiến","href":"/sang-kien"},{"label":"Hợp tác & liên hệ","href":"/lien-he"},{"label":"Sky First Network","href":"https://skyfirst.io.vn"}]},{"title":"Thông tin","items":[{"label":"Quyền riêng tư","href":"/quyen-rieng-tu"},{"label":"Điều khoản","href":"/dieu-khoan"},{"label":"Chính sách dữ liệu","href":"/chinh-sach-du-lieu"},{"label":"Khả năng tiếp cận","href":"/accessibility"},{"label":"Sitemap","href":"/sitemap"}]}]}',datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('gioi-thieu','Về Xanh Sky First','published','[{"type":"heading","text":"Không gian để sự quan tâm trở thành hành động"},{"type":"paragraph","text":"Xanh Sky First được phát triển như một không gian dành cho môi trường, cộng đồng và phát triển bền vững trong hệ sinh thái Sky First. Xanh không giới hạn mình ở một chiến dịch hoặc một hình thức tình nguyện duy nhất, mà xây dựng hành trình từ nhận thức đến hành động: tìm hiểu vấn đề, tiếp cận kiến thức, tham gia phù hợp, đóng góp chuyên môn và cùng phát triển giải pháp có căn cứ."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Bản sắc của Xanh nằm ở cách tiếp cận có chiều sâu. Trước một vấn đề, chúng tôi khuyến khích người tham gia tìm hiểu nguyên nhân, bối cảnh và những bên liên quan thay vì chỉ nhìn vào hình ảnh dễ gây chú ý. Một bài viết có nguồn đáng tin, một buổi chia sẻ có mục tiêu rõ ràng, một ý tưởng được kiểm tra trước khi thực hiện hay một thói quen bền vững đều có thể là điểm khởi đầu có ích."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Xanh hướng đến việc tạo điều kiện để người trẻ, cộng đồng địa phương, người có chuyên môn và đơn vị đồng hành có thể gặp nhau quanh những mục tiêu phù hợp. Mỗi người có thể tham gia ở mức độ khác nhau: học hỏi, chia sẻ tài nguyên, góp ý phương án, hỗ trợ truyền thông, phát triển công cụ hoặc tham gia hoạt động trực tiếp khi có chương trình được công bố. Không có một cách đóng góp duy nhất dành cho tất cả mọi người."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Trong quá trình phát triển, Xanh ưu tiên thông tin rõ ràng, mục tiêu có thể kiểm tra, phạm vi trách nhiệm phù hợp và việc ghi nhận trung thực. Chúng tôi không sử dụng số liệu chưa xác minh để tạo cảm giác thành tích, cũng không xem một chương trình hoàn tất chỉ vì sự kiện đã kết thúc. Kinh nghiệm, tài liệu, phản hồi và kết quả thực tế cần được lưu lại để các bước tiếp theo có thể học hỏi từ những gì đã diễn ra."}]','{"title":"Về Xanh Sky First | Xanh Sky First","description":"Không gian để sự quan tâm trở thành hành động. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-du-an','Dự án & sáng kiến','published','[{"type":"heading","text":"Giải pháp được phát triển từ vấn đề thực tế"},{"type":"paragraph","text":"Các dự án của Xanh Sky First được định hướng bắt đầu từ một vấn đề cụ thể, một nhóm thụ hưởng có thể xác định và một mục tiêu phù hợp với nguồn lực hiện có. Thay vì chỉ đặt tên cho một chiến dịch rồi tìm cách lấp đầy lịch hoạt động, mỗi ý tưởng cần trải qua bước tìm hiểu bối cảnh, phân tích nhu cầu, xác định rủi ro và lựa chọn phương pháp triển khai."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Một đề xuất tốt cần giải thích vì sao vấn đề đáng quan tâm, ai chịu ảnh hưởng, những giải pháp nào đã được thử nghiệm và điều gì khiến phương án đang đề xuất phù hợp. Khi chủ đề liên quan đến môi trường, nhóm thực hiện cần phân biệt giữa việc tạo ra hình ảnh đẹp và thay đổi có ý nghĩa; đồng thời cân nhắc tính an toàn, tác động lâu dài, khả năng duy trì và các hệ quả ngoài dự kiến."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Các dự án có thể bao gồm tài nguyên giáo dục, nghiên cứu cộng đồng, giải pháp giảm chất thải, công cụ hỗ trợ hành vi bền vững, hoạt động thử nghiệm tại địa phương hoặc sáng kiến hợp tác. Hình thức chỉ được lựa chọn sau khi hiểu vấn đề. Thành viên có thể đóng góp bằng nghiên cứu, thiết kế, nội dung, công nghệ, hậu cần, điều phối hoặc đánh giá, tùy năng lực và vai trò đã thống nhất."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Thông tin dự án cần được công bố theo mức độ sẵn sàng: đề xuất, đang chuẩn bị, đang triển khai, đã hoàn thành hoặc tạm dừng. Mục tiêu, tiến độ, thay đổi phạm vi và kết quả phải được cập nhật đúng thực tế. Nếu dự án chưa có đối tác, ngân sách, địa điểm hay số liệu xác nhận, website phải nói rõ điều đó thay vì khiến người đọc hiểu nhầm rằng dự án đã triển khai."}]','{"title":"Dự án & sáng kiến | Xanh Sky First","description":"Giải pháp được phát triển từ vấn đề thực tế. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-hoat-dong','Hoạt động & sự kiện','published','[{"type":"heading","text":"Mỗi hoạt động cần có mục tiêu, người phụ trách và kết quả rõ ràng"},{"type":"paragraph","text":"Khu vực Hoạt động tập hợp những chương trình cộng đồng, buổi chia sẻ, hoạt động giáo dục, sự kiện hoặc hình thức tham gia khác đã được Xanh Sky First công bố. Mỗi thông tin hoạt động cần giúp người đọc nhanh chóng hiểu mục đích, đối tượng phù hợp, thời gian, địa điểm, yêu cầu chuẩn bị và cách đăng ký. Những thông tin chưa xác nhận không được trình bày như lịch đã chốt."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Một hoạt động được chuẩn bị có trách nhiệm cần xác định người chịu trách nhiệm, điều phối an toàn, cách liên hệ khi phát sinh thay đổi và phương án phù hợp với điều kiện thực tế. Với các hoạt động ngoài trời hoặc có thu gom chất thải, nội dung hướng dẫn nên nêu rõ phạm vi, thiết bị bảo hộ, cách phân loại và bàn giao chất thải, cũng như giới hạn công việc mà người tham gia có thể thực hiện."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Thông tin trước hoạt động nên được cập nhật kịp thời khi thời gian hoặc địa điểm thay đổi. Sau khi kết thúc, phần tổng kết cần ghi nhận diễn biến, kinh nghiệm, điểm còn hạn chế và dữ liệu có thể kiểm chứng. Hình ảnh minh họa không thay thế cho việc xác minh số người tham gia, khối lượng chất thải hay kết quả thực tế; các con số phải có nguồn và người xác nhận phù hợp."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh hướng đến trải nghiệm tham gia dễ hiểu, tôn trọng người đóng góp và phù hợp với các mức độ năng lực khác nhau. Người mới cần được cung cấp hướng dẫn rõ ràng; người có chuyên môn cần biết phạm vi nhiệm vụ; người không thể tham dự trực tiếp vẫn có thể đóng góp ở những phần việc phù hợp khi chương trình cho phép. Hoạt động chỉ được mở đăng ký khi có thông tin đủ để người tham gia đưa ra lựa chọn có hiểu biết."}]','{"title":"Hoạt động & sự kiện | Xanh Sky First","description":"Mỗi hoạt động cần có mục tiêu, người phụ trách và kết quả rõ ràng. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-con-nguoi','Con người Xanh','published','[{"type":"heading","text":"Tôn trọng đóng góp, vai trò và giới hạn của mỗi người"},{"type":"paragraph","text":"Xanh Sky First nhìn nhận con người là một phần quan trọng của quá trình tạo ra thay đổi, nhưng không xem số lượng thành viên là thước đo duy nhất cho sức mạnh cộng đồng. Một môi trường đóng góp lành mạnh cần mục tiêu dễ hiểu, vai trò rõ ràng, cơ chế trao đổi phù hợp và sự tôn trọng giữa những người tham gia. Người mới có thể học hỏi; người có kinh nghiệm có thể hướng dẫn; người có chuyên môn có thể đóng góp trong phạm vi đã thống nhất."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Thông tin giới thiệu nhân sự chỉ được công khai khi chính người liên quan đã đồng ý và dữ liệu đã được xác nhận. Chức danh, kinh nghiệm, hình ảnh và mô tả vai trò phải phản ánh đúng thực tế, tránh tạo ra ấn tượng về bộ máy hoặc đội ngũ chưa tồn tại. Mỗi hồ sơ nên tập trung vào phần thông tin có ích cho cộng đồng, thay vì công bố dữ liệu riêng tư không cần thiết."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Khi phối hợp trong nhóm, Xanh khuyến khích trao đổi tôn trọng, phân công phù hợp với năng lực và thời gian, phản hồi dựa trên hành vi hoặc kết quả công việc thay vì công kích cá nhân. Các nhiệm vụ cần được giao kèm mục tiêu, đầu ra và người hỗ trợ khi cần. Nếu một người không thể tiếp tục, việc bàn giao rõ ràng giúp công việc không phụ thuộc hoàn toàn vào một cá nhân."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Cộng đồng bền vững cũng cần quan tâm đến an toàn, quyền riêng tư và sự khác biệt giữa các thành viên. Thông tin hồ sơ chỉ được tiếp cận theo quyền được cấp; hình ảnh và câu chuyện cá nhân cần có căn cứ sử dụng phù hợp. Xanh hướng đến ghi nhận công bằng những đóng góp thực tế, chia sẻ bài học hữu ích và xây dựng môi trường nơi mọi người có thể đóng góp mà không bị gây áp lực phải thể hiện thành tích."}]','{"title":"Con người Xanh | Xanh Sky First","description":"Tôn trọng đóng góp, vai trò và giới hạn của mỗi người. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-co-hoi','Cơ hội dành cho người trẻ','published','[{"type":"heading","text":"Tìm cách đóng góp phù hợp với năng lực và điều kiện của bạn"},{"type":"paragraph","text":"Cơ hội tại Xanh Sky First không nhất thiết chỉ là một vị trí tình nguyện cố định. Tùy từng giai đoạn, hình thức đóng góp có thể gồm hỗ trợ nghiên cứu, viết và biên tập nội dung, thiết kế, công nghệ, tổ chức hoạt động, kết nối cộng đồng, biên soạn tài liệu hoặc đề xuất giải pháp. Mỗi cơ hội cần mô tả mục tiêu, yêu cầu, thời lượng dự kiến và đầu mối liên hệ để người quan tâm hiểu rõ trước khi đăng ký."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Không phải ai cũng có cùng quỹ thời gian, điều kiện di chuyển hay kinh nghiệm. Vì vậy, một mô tả cơ hội tốt cần phân biệt việc có thể làm từ xa với nhiệm vụ phải có mặt trực tiếp, nêu rõ phần việc bắt buộc và phần việc có thể linh hoạt, đồng thời tránh hứa hẹn lợi ích không có căn cứ. Người đăng ký nên được khuyến khích lựa chọn theo khả năng thực tế, không phải theo áp lực chứng minh sự nhiệt tình."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Với cơ hội cần kỹ năng cụ thể, Xanh có thể đề nghị người tham gia gửi ví dụ công việc, mô tả kinh nghiệm hoặc hoàn thành một bước trao đổi phù hợp. Thông tin yêu cầu phải tương xứng với nhiệm vụ và chỉ được thu thập trong phạm vi cần thiết. Kết quả tiếp nhận nên có thông báo rõ ràng; nếu chưa phù hợp ở thời điểm hiện tại, người đăng ký vẫn cần được đối xử tôn trọng."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Cơ hội chỉ được hiển thị khi đã được phê duyệt và có thông tin đủ để tham gia. Nếu số lượng tiếp nhận có giới hạn, thời hạn đăng ký hoặc điều kiện tham gia thay đổi, hệ thống phải cập nhật kịp thời. Xanh hướng đến kết nối đúng người với đúng việc, tạo trải nghiệm có ý nghĩa và giữ cho lời mời đóng góp luôn trung thực với nhu cầu thực tế."}]','{"title":"Cơ hội dành cho người trẻ | Xanh Sky First","description":"Tìm cách đóng góp phù hợp với năng lực và điều kiện của bạn. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-tai-nguyen','Kiến thức & tài nguyên','published','[{"type":"heading","text":"Hiểu vấn đề tốt hơn để lựa chọn hành động phù hợp"},{"type":"paragraph","text":"Thư viện Xanh được định hướng là nơi tập hợp tài liệu, hướng dẫn, bài giải thích, công cụ và nguồn tham khảo giúp người đọc tiếp cận vấn đề môi trường theo cách rõ ràng hơn. Tài nguyên nên bắt đầu từ câu hỏi thật mà người đọc thường gặp, giải thích thuật ngữ khi cần và trình bày đủ bối cảnh để tránh biến một lời khuyên đơn giản thành quy tắc áp dụng cho mọi hoàn cảnh."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Nội dung môi trường thường liên quan đến nhiều yếu tố: hành vi tiêu dùng, hạ tầng thu gom, điều kiện địa phương, công nghệ, kinh tế và chính sách. Vì thế, khi đưa ra khuyến nghị, tài liệu cần phân biệt thông tin đã có bằng chứng với góc nhìn hoặc đề xuất. Nguồn tham khảo nên được ghi nhận rõ ràng; ngày cập nhật cần thể hiện khi thông tin có thể thay đổi theo thời gian."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Tài nguyên có thể phục vụ nhiều nhóm người đọc, từ học sinh, sinh viên đến người điều phối hoạt động, giáo viên, nhóm cộng đồng hoặc người đang tìm cách thay đổi thói quen. Mỗi tài liệu nên nêu đối tượng phù hợp, cách sử dụng, điều kiện cần biết và giới hạn của nội dung. Các mẫu biểu, checklist và hướng dẫn thực hành cần có ngôn ngữ dễ hiểu, dễ tiếp cận và có thể điều chỉnh cho bối cảnh thực tế."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Thư viện không chỉ là nơi lưu trữ tệp mà còn cần được cập nhật, phân loại và rà soát. Khi tài liệu lỗi thời hoặc có thông tin cần hiệu chỉnh, người quản trị nên cập nhật phiên bản và giữ lại dấu vết thay đổi. Xanh khuyến khích việc chia sẻ tài nguyên có quyền sử dụng phù hợp và tôn trọng công sức của tác giả, đồng thời không trình bày nội dung tham khảo như kết quả nghiên cứu do Xanh tự thực hiện nếu không đúng."}]','{"title":"Kiến thức & tài nguyên | Xanh Sky First","description":"Hiểu vấn đề tốt hơn để lựa chọn hành động phù hợp. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-tin-tuc','Tin tức & câu chuyện','published','[{"type":"heading","text":"Thông tin có bối cảnh, câu chuyện có sự tôn trọng"},{"type":"paragraph","text":"Tin tức và câu chuyện là nơi Xanh Sky First chia sẻ những cập nhật đã được kiểm tra, kiến thức liên quan đến môi trường, bài học từ quá trình chuẩn bị hoặc triển khai, cùng những góc nhìn hữu ích từ cộng đồng. Mỗi bài cần giúp người đọc phân biệt đâu là thông tin, đâu là ý kiến và đâu là định hướng đang được xem xét. Tiêu đề cần chính xác, không phóng đại sự kiện hoặc tạo cảm giác có thành tích chưa được xác minh."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Với bài viết về hoạt động, nội dung nên nêu bối cảnh, mục tiêu, người tổ chức, thời gian và kết quả ở mức đã có căn cứ. Hình ảnh cần có nguồn hợp lệ và mô tả phù hợp; người xuất hiện trong ảnh phải được tôn trọng quyền riêng tư. Không dùng ảnh minh họa để khiến người đọc tưởng rằng Xanh đã tổ chức một hoạt động chưa diễn ra. Khi bài viết nói về dữ liệu, phải cho biết đơn vị, kỳ thống kê và cách hiểu chỉ số."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Câu chuyện cộng đồng cần được kể có sự đồng thuận, không tiết lộ thông tin riêng tư hoặc khai thác khó khăn của người khác chỉ để tạo cảm xúc. Trích dẫn cần đúng ngữ cảnh; nội dung biên tập không làm thay đổi ý nghĩa lời nói. Khi có thông tin sai hoặc cần cập nhật, bài viết phải có quy trình sửa đổi minh bạch để người đọc hiểu phần nào đã thay đổi và vì sao."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh ưu tiên nội dung có thể giúp người đọc hiểu sâu hơn hoặc đưa ra lựa chọn tốt hơn, không chỉ nội dung có khả năng thu hút tương tác ngắn hạn. Bài viết có thể liên kết tới tài nguyên, dự án hoặc cơ hội liên quan nhưng không nên dùng lời kêu gọi quá mức. Khu vực tin tức phải giữ được sự cân bằng giữa thông tin chính thức, nội dung hướng dẫn và câu chuyện phản ánh những kinh nghiệm thực tế."}]','{"title":"Tin tức & câu chuyện | Xanh Sky First","description":"Thông tin có bối cảnh, câu chuyện có sự tôn trọng. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-tham-gia','Tham gia cùng Xanh','published','[{"type":"heading","text":"Chọn một cách bắt đầu phù hợp với bạn"},{"type":"paragraph","text":"Bạn không cần có sẵn kinh nghiệm môi trường để tìm hiểu và bắt đầu đóng góp cùng Xanh Sky First. Tùy chương trình đang được công bố, người quan tâm có thể tham gia hoạt động, đăng ký cơ hội, đóng góp chuyên môn, chia sẻ tài nguyên, gửi đề xuất sáng kiến hoặc nhận thông tin qua newsletter. Mỗi lựa chọn nên đi kèm phần mô tả rõ ràng để bạn hiểu mình đang đăng ký điều gì và thông tin được sử dụng ra sao."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Trước khi gửi biểu mẫu, hãy đọc các yêu cầu về thời gian, địa điểm, điều kiện tham gia và nội dung đồng ý. Chỉ cung cấp các thông tin cần thiết cho mục đích đã nêu; không gửi tài liệu nhạy cảm nếu biểu mẫu không yêu cầu. Nếu chưa thể tham gia trực tiếp, bạn có thể tìm những phần việc phù hợp hơn với khả năng hoặc theo dõi tài nguyên để chuẩn bị trước khi có cơ hội phù hợp."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Mỗi biểu mẫu đang mở cần hiển thị tên chương trình, mô tả, trạng thái tiếp nhận và thời hạn nếu có. Sau khi gửi thành công, hệ thống sẽ thông báo và cung cấp mã hồ sơ khi quy trình có hỗ trợ. Người đăng ký nên lưu mã để tra cứu trạng thái. Việc gửi hồ sơ không đồng nghĩa với việc tự động được chấp nhận; kết quả phụ thuộc vào thông tin, yêu cầu của chương trình và bước xử lý của người phụ trách."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Xanh hướng đến quy trình tiếp nhận tôn trọng người đăng ký. Thông tin hồ sơ được giới hạn cho người có quyền xử lý, không công khai lên website. Khi có cập nhật trạng thái, người gửi cần nhận được thông báo phù hợp nếu chức năng đó đã được cấu hình. Nếu thay đổi kế hoạch, người tham gia nên dùng kênh liên hệ được công bố để thông báo, thay vì cảm thấy phải duy trì một cam kết vượt quá điều kiện của mình."}]','{"title":"Tham gia cùng Xanh | Xanh Sky First","description":"Chọn một cách bắt đầu phù hợp với bạn. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('page-tra-cuu','Tra cứu hồ sơ','published','[{"type":"heading","text":"Theo dõi trạng thái bằng thông tin chính xác"},{"type":"paragraph","text":"Khu vực tra cứu giúp người đã gửi biểu mẫu xem trạng thái xử lý của hồ sơ khi hệ thống đã cấp mã tiếp nhận tương ứng. Mã hồ sơ nên được lưu lại sau khi gửi thành công; khi cần tra cứu, hãy nhập đúng toàn bộ mã, tránh nhầm ký tự hoặc khoảng trắng. Nếu hệ thống không tìm thấy hồ sơ, trước tiên hãy kiểm tra mã được cấp và thử lại trước khi gửi yêu cầu hỗ trợ."},{"type":"heading","text":"Cách tiếp cận của Xanh"},{"type":"paragraph","text":"Kết quả tra cứu chỉ nên hiển thị lượng thông tin cần thiết để người gửi nhận biết hồ sơ và trạng thái hiện tại. Dữ liệu cá nhân, câu trả lời biểu mẫu, tệp đính kèm và ghi chú nội bộ không được đưa ra công khai qua mã tra cứu đơn giản. Các trạng thái như đã tiếp nhận, đang xem xét, cần bổ sung, đã duyệt hoặc đã hoàn tất cần có ý nghĩa rõ ràng và được cập nhật bởi người có quyền."},{"type":"heading","text":"Cách cộng đồng có thể tham gia"},{"type":"paragraph","text":"Tra cứu hồ sơ tham gia Xanh khác với tra cứu giấy chứng nhận hoặc văn bản được cấp trên các cổng khác của hệ sinh thái Sky First. Website cần chỉ dẫn đúng nơi xử lý từng loại mã, tránh khiến người dùng nhầm lẫn giữa mã đăng ký và mã tài liệu. Nếu chuyển sang hệ thống khác, liên kết phải có nguồn chính thức và mở theo cách dễ hiểu."},{"type":"heading","text":"Minh bạch và học hỏi"},{"type":"paragraph","text":"Nếu gặp lỗi tra cứu kéo dài, người dùng có thể liên hệ qua kênh hỗ trợ được công bố, cung cấp mã hồ sơ và mô tả lỗi ở mức cần thiết. Không nên gửi mật khẩu, mã xác thực hoặc dữ liệu nhạy cảm qua phần bình luận công khai. Xanh hướng đến một quy trình tra cứu rõ ràng, bảo vệ quyền riêng tư và thể hiện trạng thái dựa trên dữ liệu thực trong hệ thống."}]','{"title":"Tra cứu hồ sơ | Xanh Sky First","description":"Theo dõi trạng thái bằng thông tin chính xác. Tìm hiểu định hướng, cách tiếp cận và các nguyên tắc của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('gioi-thieu-nguyen-tac','Bốn nguyên tắc hành động','published','[{"type":"heading","text":"Bốn nguyên tắc giúp Xanh giữ sự nhất quán giữa nhận thức, cách làm và kết quả."},{"type":"paragraph","text":"Hiểu đúng trước khi hành động giúp người tham gia đặt câu hỏi, kiểm tra nguồn và hiểu bối cảnh trước khi lựa chọn giải pháp. Hành động từ những điều có thể thực hiện yêu cầu mục tiêu, người phụ trách, cách ghi nhận và bước tổng kết rõ ràng. Kết nối để cùng tạo thay đổi nhấn mạnh chất lượng hợp tác thay vì chỉ tăng số lượng kết nối. Theo đuổi giá trị bền vững nghĩa là lưu lại kinh nghiệm, tài liệu, dữ liệu và bài học sau khi chương trình kết thúc."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Các nguyên tắc này không phải khẩu hiệu trang trí mà là tiêu chí để xem xét đề xuất, thiết kế hoạt động, biên soạn tài nguyên và cập nhật kết quả. Khi một lựa chọn chưa phù hợp với điều kiện thực tế, việc điều chỉnh phạm vi hoặc hoãn triển khai có thể có trách nhiệm hơn là cố tổ chức để tạo hình ảnh. Xanh khuyến khích người tham gia nêu câu hỏi, phản hồi có căn cứ và ghi lại những điểm chưa đạt để các lần sau làm tốt hơn."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Trong thực hành, một nguyên tắc cần được chuyển thành những câu hỏi cụ thể: vấn đề đã được hiểu đúng chưa, mục tiêu có đo lường được không, vai trò đã rõ chưa, dữ liệu có thể kiểm tra không và kết quả có thể tiếp tục được sử dụng như thế nào. Những câu hỏi này giúp nhóm tránh hành động theo cảm tính hoặc theo xu hướng ngắn hạn."}]','{"title":"Bốn nguyên tắc hành động | Xanh Sky First","description":"Bốn nguyên tắc giúp Xanh giữ sự nhất quán giữa nhận thức, cách làm và kết quả. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('gioi-thieu-linh-vuc','Năm lĩnh vực hành động','published','[{"type":"heading","text":"Năm lĩnh vực định hướng những chủ đề mà Xanh có thể phát triển nội dung, tài nguyên, sáng kiến và hoạt động cộng đồng."},{"type":"paragraph","text":"Môi trường và không gian sống tập trung vào chất lượng nơi ở, rác thải, cảnh quan và cách cộng đồng sử dụng không gian chung. Giáo dục môi trường cung cấp kiến thức, công cụ học tập và cơ hội trao đổi. Lối sống và tiêu dùng bền vững giúp người đọc xem xét thói quen sử dụng tài nguyên, mua sắm, tái sử dụng và lựa chọn sản phẩm trong bối cảnh thực tế."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Đổi mới và sáng kiến xanh là không gian để đề xuất, kiểm tra và cải thiện các ý tưởng hoặc công cụ có thể giải quyết vấn đề cụ thể. Cộng đồng và phát triển bền vững chú ý đến khả năng tham gia của nhiều nhóm người, sự phù hợp với địa phương, tính công bằng và duy trì giá trị sau một chương trình. Các lĩnh vực có thể giao nhau; điều quan trọng là mỗi nội dung cần giải thích rõ vấn đề và mục tiêu chính."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Danh mục lĩnh vực không phải lời khẳng định rằng tất cả chương trình đã được triển khai. Đây là khung để tổ chức nội dung và đánh giá đề xuất trong từng giai đoạn. Một sáng kiến chỉ nên được giới thiệu như hoạt động đang thực hiện khi đã có kế hoạch được duyệt và thông tin cần thiết; ý tưởng mới cần được gắn trạng thái đề xuất hoặc đang phát triển."}]','{"title":"Năm lĩnh vực hành động | Xanh Sky First","description":"Năm lĩnh vực định hướng những chủ đề mà Xanh có thể phát triển nội dung, tài nguyên, sáng kiến và hoạt động cộng đồng. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('du-an-dinh-huong','Định hướng phát triển dự án','published','[{"type":"heading","text":"Trang này trình bày cách một ý tưởng được chuyển thành đề xuất có thể đánh giá và triển khai."},{"type":"paragraph","text":"Một đề xuất cần mô tả vấn đề, bối cảnh địa phương, nhóm chịu ảnh hưởng và bằng chứng ban đầu. Nhóm xây dựng nên xác định điều gì đã biết, điều gì còn cần tìm hiểu và giả định nào có thể làm thay đổi giải pháp. Bước chuẩn bị này giúp tránh lựa chọn hoạt động chỉ vì dễ tổ chức hoặc dễ truyền thông mà chưa chắc phù hợp với nhu cầu thật."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Sau khi làm rõ vấn đề, cần xác định mục tiêu, phạm vi, sản phẩm đầu ra, người phụ trách, nguồn lực, lịch dự kiến và các rủi ro có thể gặp. Mục tiêu nên đủ cụ thể để đánh giá nhưng không buộc nhóm phải hứa hẹn kết quả ngoài khả năng kiểm soát. Với dự án môi trường, yếu tố an toàn, quản lý chất thải, quyền sử dụng hình ảnh và tác động ngoài dự kiến cần được cân nhắc ngay từ đầu."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Đề xuất được xem xét dựa trên mức độ phù hợp với định hướng Xanh, tính khả thi, lợi ích cộng đồng, tính minh bạch và khả năng học hỏi từ kết quả. Việc được tiếp nhận ý tưởng không đồng nghĩa dự án tự động được tài trợ hoặc triển khai. Trạng thái và các bước tiếp theo cần được phản hồi rõ ràng cho người đề xuất."}]','{"title":"Định hướng phát triển dự án | Xanh Sky First","description":"Trang này trình bày cách một ý tưởng được chuyển thành đề xuất có thể đánh giá và triển khai. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('du-an-sang-kien','Sáng kiến xanh','published','[{"type":"heading","text":"Sáng kiến là cơ hội để biến câu hỏi thực tế thành phương án có thể thử nghiệm và cải thiện."},{"type":"paragraph","text":"Một sáng kiến có thể bắt đầu từ vấn đề nhỏ trong khu dân cư, trường học, không gian công cộng hoặc thói quen tiêu dùng. Người đề xuất nên mô tả vấn đề quan sát được, ai gặp khó khăn, giải pháp hiện có và điểm cần cải thiện. Cách diễn đạt rõ ràng giúp nhóm khác hiểu ý tưởng mà không phải dựa vào những lời mô tả chung chung như “xây dựng môi trường xanh hơn”."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Ý tưởng cần được đánh giá về khả năng thực hiện, chi phí, nguồn lực, độ an toàn, tác động tới các nhóm khác nhau và cách xác định hiệu quả. Với giải pháp mới, thử nghiệm ở phạm vi nhỏ thường giúp tìm ra hạn chế trước khi mở rộng. Nếu chưa có dữ liệu chứng minh hiệu quả, cần nói đó là giả thuyết hoặc kỳ vọng thay vì tuyên bố giải pháp đã tạo ra tác động."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh khuyến khích việc ghi lại quá trình thử nghiệm, phản hồi của người sử dụng, các điều chỉnh và bài học rút ra. Một phương án chưa đạt mục tiêu vẫn có thể tạo ra tri thức có giá trị nếu kết quả được ghi nhận trung thực. Những sáng kiến phù hợp có thể được phát triển thêm khi có người phụ trách, điều kiện và nguồn lực rõ ràng."}]','{"title":"Sáng kiến xanh | Xanh Sky First","description":"Sáng kiến là cơ hội để biến câu hỏi thực tế thành phương án có thể thử nghiệm và cải thiện. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('hoat-dong-lich','Lịch hoạt động','published','[{"type":"heading","text":"Lịch hoạt động chỉ công bố thông tin đã được xác nhận để người tham gia chủ động sắp xếp."},{"type":"paragraph","text":"Mỗi hoạt động nên hiển thị thời gian, địa điểm, mục tiêu, đối tượng phù hợp, yêu cầu chuẩn bị và thời hạn đăng ký khi có. Nếu thông tin vẫn đang chờ xác nhận, trang cần thể hiện trạng thái dự kiến hoặc chưa mở đăng ký. Không sử dụng ngày giả chỉ để tạo cảm giác website đang hoạt động liên tục."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Trước khi đăng ký, người tham gia nên kiểm tra hướng dẫn về di chuyển, thiết bị bảo hộ, điều kiện thời tiết hoặc các yêu cầu đặc thù. Với hoạt động ngoài trời, đơn vị tổ chức cần có người điều phối, phương án liên hệ khi phát sinh thay đổi và hướng dẫn an toàn ở mức phù hợp. Những nội dung này giúp người mới hiểu mình cần làm gì và nơi tìm trợ giúp khi cần."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Khi lịch thay đổi, thông tin mới cần được cập nhật nhất quán trên trang, biểu mẫu và thông báo đã gửi. Sau khi kết thúc, hoạt động có thể được chuyển sang trạng thái hoàn thành và bổ sung phần tổng kết đã xác minh. Lịch sử thông tin giúp cộng đồng hiểu điều gì đã diễn ra và hỗ trợ việc lập kế hoạch cho lần tiếp theo."}]','{"title":"Lịch hoạt động | Xanh Sky First","description":"Lịch hoạt động chỉ công bố thông tin đã được xác nhận để người tham gia chủ động sắp xếp. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('hoat-dong-huong-dan','Hướng dẫn tham gia hoạt động','published','[{"type":"heading","text":"Mỗi chương trình cần cung cấp hướng dẫn đủ rõ để người mới có thể chuẩn bị an toàn và chủ động."},{"type":"paragraph","text":"Trước hết, hãy đọc mục tiêu, thời gian, địa điểm và phạm vi công việc của hoạt động. Nếu chưa rõ điều kiện tham gia, hãy liên hệ đầu mối được công bố trước khi di chuyển. Người tham gia nên báo những giới hạn quan trọng liên quan đến thời gian hoặc khả năng thực hiện nhiệm vụ để nhóm điều phối có thể phân công phù hợp."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Với hoạt động ngoài trời hoặc thu gom chất thải, hãy tuân thủ hướng dẫn của người phụ trách, sử dụng trang bị phù hợp và không tự xử lý vật sắc nhọn, hóa chất, chất thải y tế hoặc các vật liệu không xác định. Không đặt mình vào tình huống nguy hiểm chỉ để hoàn thành nhiệm vụ hoặc tạo hình ảnh. Khi gặp sự cố, dừng công việc và báo người điều phối."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau hoạt động, hãy hỗ trợ việc thu dọn, bàn giao vật dụng và chia sẻ phản hồi trung thực. Nếu có biểu mẫu tổng kết, chỉ cung cấp thông tin mà mình biết hoặc trực tiếp quan sát. Hình ảnh cá nhân và hình ảnh của người khác cần được chia sẻ với sự tôn trọng. Những phản hồi cụ thể giúp chương trình cải thiện cách tổ chức và nâng cao trải nghiệm cho những người tham gia sau."}]','{"title":"Hướng dẫn tham gia hoạt động | Xanh Sky First","description":"Mỗi chương trình cần cung cấp hướng dẫn đủ rõ để người mới có thể chuẩn bị an toàn và chủ động. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('con-nguoi-vai-tro','Vai trò và cách phối hợp','published','[{"type":"heading","text":"Vai trò rõ ràng giúp mỗi người biết phạm vi trách nhiệm, đầu ra và cách phối hợp với các thành viên khác."},{"type":"paragraph","text":"Một vai trò nên được mô tả bằng nhiệm vụ, phạm vi quyết định, người phối hợp và tiêu chí hoàn thành thay vì chỉ bằng tên chức danh. Đối với nhiệm vụ ngắn hạn, mô tả rõ đầu ra và hạn hoàn thành thường có ích hơn việc tạo thêm tầng nấc tổ chức. Khi vai trò thay đổi, người liên quan cần được thông báo và dữ liệu công khai phải được cập nhật."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Phối hợp hiệu quả đòi hỏi thông tin được chia sẻ đúng người, đúng thời điểm và qua kênh phù hợp. Các cuộc họp nên có mục tiêu, nội dung chuẩn bị và kết luận có thể theo dõi. Công việc cần được ghi nhận để tránh phụ thuộc vào trí nhớ của một cá nhân. Khi có bất đồng, nhóm nên làm rõ dữ kiện, trách nhiệm và tác động thay vì suy đoán động cơ hoặc công kích cá nhân."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh hướng đến cách phối hợp tôn trọng khả năng và giới hạn của từng người. Thành viên nên được quyền nêu khó khăn, đề nghị hỗ trợ hoặc báo không thể tiếp tục một nhiệm vụ. Việc bàn giao rõ ràng, lưu tài liệu và phản hồi có xây dựng giúp công việc tiếp tục mà không tạo áp lực không cần thiết."}]','{"title":"Vai trò và cách phối hợp | Xanh Sky First","description":"Vai trò rõ ràng giúp mỗi người biết phạm vi trách nhiệm, đầu ra và cách phối hợp với các thành viên khác. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('con-nguoi-quyen-rieng-tu','Thông tin và quyền riêng tư','published','[{"type":"heading","text":"Việc giới thiệu con người cần dựa trên sự đồng ý, tính chính xác và mục đích công khai rõ ràng."},{"type":"paragraph","text":"Hồ sơ công khai nên tập trung vào tên, vai trò, lĩnh vực đóng góp và thông tin giới thiệu mà người liên quan đã đồng ý chia sẻ. Không cần công khai địa chỉ riêng, thông tin liên hệ cá nhân, giấy tờ định danh hoặc dữ liệu không phục vụ mục đích giới thiệu. Ảnh chân dung cũng cần có quyền sử dụng phù hợp và văn bản thay thế hỗ trợ người dùng công nghệ hỗ trợ."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Quản trị viên cần phân biệt hồ sơ nội bộ với hồ sơ công khai. Việc có dữ liệu trong Management Center không tự động có nghĩa dữ liệu được phép hiển thị ngoài website hoặc cho công cụ tìm kiếm lập chỉ mục. Khi vai trò kết thúc hoặc người liên quan yêu cầu chỉnh sửa phù hợp, thông tin cần được rà soát theo quy trình và giữ nhật ký cần thiết."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Câu chuyện cá nhân phải được trình bày đúng ngữ cảnh và không khai thác hoàn cảnh riêng tư để tạo cảm xúc. Nếu sử dụng trích dẫn, hình ảnh hay nội dung do người khác cung cấp, cần làm rõ sự đồng ý và phạm vi sử dụng. Cách quản lý thận trọng giúp Xanh duy trì lòng tin và giảm rủi ro cho cộng đồng."}]','{"title":"Thông tin và quyền riêng tư | Xanh Sky First","description":"Việc giới thiệu con người cần dựa trên sự đồng ý, tính chính xác và mục đích công khai rõ ràng. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('co-hoi-tinh-nguyen','Cơ hội tình nguyện','published','[{"type":"heading","text":"Tình nguyện là một cách đóng góp, nhưng nhiệm vụ cần phù hợp với năng lực, thời gian và điều kiện của mỗi người."},{"type":"paragraph","text":"Mô tả cơ hội tình nguyện cần làm rõ mục tiêu, phần việc, địa điểm, thời lượng dự kiến, yêu cầu tối thiểu và đầu mối hỗ trợ. Nếu nhiệm vụ cần có mặt trực tiếp, điều đó phải được nêu rõ trước khi người dùng gửi hồ sơ. Nếu có thể làm trực tuyến, trang nên mô tả cách giao việc, cách trao đổi và cách bàn giao kết quả."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Người quan tâm không nhất thiết phải có kinh nghiệm chuyên môn từ đầu, nhưng cần hiểu cam kết cụ thể của nhiệm vụ. Các yêu cầu về tuổi, người giám hộ, an toàn hoặc kỹ năng cần tương xứng với bối cảnh thực tế và được thông báo trước. Không yêu cầu ứng viên cung cấp tài liệu không cần thiết; không hứa hẹn giấy chứng nhận, hỗ trợ hoặc quyền lợi chưa được phê duyệt."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi gửi hồ sơ, người đăng ký nên nhận xác nhận tiếp nhận nếu hệ thống đã lưu thành công. Việc xét chọn cần dựa trên nhu cầu thật và tiêu chí đã công bố. Nếu không được nhận ở thời điểm hiện tại, người đăng ký có thể theo dõi cơ hội khác hoặc đóng góp theo hình thức phù hợp hơn."}]','{"title":"Cơ hội tình nguyện | Xanh Sky First","description":"Tình nguyện là một cách đóng góp, nhưng nhiệm vụ cần phù hợp với năng lực, thời gian và điều kiện của mỗi người. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('co-hoi-chuyen-mon','Đóng góp chuyên môn','published','[{"type":"heading","text":"Chuyên môn có thể giúp một sáng kiến trở nên rõ ràng, khả thi và có cơ sở hơn."},{"type":"paragraph","text":"Xanh có thể tiếp nhận đóng góp từ nhiều lĩnh vực phù hợp như giáo dục, thiết kế, công nghệ, truyền thông, dữ liệu, tổ chức hoạt động, nghiên cứu, quản lý dự án và phát triển cộng đồng. Mỗi lời mời cần nêu vấn đề cần giải quyết, đầu ra mong đợi, thời gian dự kiến và mức độ phối hợp. Cách mô tả cụ thể giúp người quan tâm đánh giá xem năng lực của họ có phù hợp hay không."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Khi chuyên gia hoặc người đóng góp chia sẻ tài liệu, công cụ hay ý kiến, hai bên nên thống nhất phạm vi sử dụng, quyền sở hữu, ghi nhận đóng góp và điều kiện bảo mật nếu có. Không nên coi một cuộc trao đổi ban đầu là cam kết hợp tác dài hạn. Thỏa thuận cần phù hợp với quy mô công việc và không tạo ra kỳ vọng không có cơ sở."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Đóng góp chuyên môn không chỉ là đưa ra câu trả lời mà còn giúp đặt câu hỏi đúng, nhận diện rủi ro và chỉ ra giới hạn của phương án. Xanh khuyến khích cách làm có giải thích và tài liệu hóa để người khác có thể học hỏi. Mọi kết quả công bố cần được rà soát về tính chính xác và không được gán danh nghĩa chuyên gia khi chưa có sự đồng ý."}]','{"title":"Đóng góp chuyên môn | Xanh Sky First","description":"Chuyên môn có thể giúp một sáng kiến trở nên rõ ràng, khả thi và có cơ sở hơn. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('tai-nguyen-giao-duc','Giáo dục môi trường','published','[{"type":"heading","text":"Tài nguyên giáo dục cần giúp người học hiểu bối cảnh và thực hành được điều đã học."},{"type":"paragraph","text":"Một tài liệu giáo dục tốt có mục tiêu học tập rõ ràng, giải thích thuật ngữ, ví dụ dễ liên hệ và hoạt động thực hành phù hợp với lứa tuổi hoặc nhóm người đọc. Với chủ đề môi trường, người học cần hiểu cả lựa chọn cá nhân lẫn điều kiện hệ thống như hạ tầng thu gom, khả năng tiếp cận sản phẩm thay thế và bối cảnh địa phương. Tránh biến nội dung phức tạp thành thông điệp đơn giản nhưng gây hiểu nhầm."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Tài nguyên có thể gồm bài đọc, hướng dẫn thảo luận, bảng kiểm, mẫu quan sát, câu hỏi phản tư hoặc hoạt động nhóm. Nội dung cần chỉ rõ điều kiện sử dụng và nguồn tham khảo. Khi sử dụng hình ảnh hoặc tài liệu bên ngoài, cần tôn trọng quyền tác giả và ghi nhận nguồn. Tài liệu nên được rà soát định kỳ, nhất là những phần có dữ liệu hoặc khuyến nghị thay đổi theo thời gian."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Người sử dụng có thể gửi phản hồi về độ dễ hiểu, tính phù hợp và những điểm còn thiếu. Việc cải tiến nên dựa trên phản hồi cụ thể, không chỉ lượt xem. Xanh hướng đến tài nguyên giúp người học tự đặt câu hỏi, phân biệt bằng chứng với ý kiến và biết cách chuyển kiến thức thành lựa chọn an toàn, phù hợp với hoàn cảnh thật."}]','{"title":"Giáo dục môi trường | Xanh Sky First","description":"Tài nguyên giáo dục cần giúp người học hiểu bối cảnh và thực hành được điều đã học. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('tai-nguyen-song-xanh','Lối sống và tiêu dùng bền vững','published','[{"type":"heading","text":"Thay đổi thói quen bền vững bắt đầu bằng lựa chọn khả thi, không phải cảm giác hoàn hảo."},{"type":"paragraph","text":"Lối sống bền vững có thể liên quan đến việc sử dụng đồ dùng lâu hơn, giảm lãng phí, lựa chọn phương tiện phù hợp, sử dụng tài nguyên tiết kiệm và tìm hiểu cách xử lý chất thải tại địa phương. Không phải lựa chọn nào cũng phù hợp với mọi người; chi phí, điều kiện sống, khả năng tiếp cận dịch vụ và thời gian đều ảnh hưởng đến cách áp dụng. Nội dung hướng dẫn nên giúp người đọc cân nhắc chứ không phán xét."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Một lời khuyên cần giải thích điều kiện và giới hạn. Ví dụ, tái sử dụng chỉ hữu ích khi món đồ phù hợp với mục đích, được vệ sinh đúng cách và không tạo ra rủi ro mới. Phân loại rác cần gắn với khả năng thu gom và xử lý thực tế, bởi việc phân loại ở nhà không bảo đảm kết quả nếu hệ thống tiếp nhận chưa đáp ứng. Những khác biệt này nên được trình bày rõ để tránh kỳ vọng sai."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Xanh khuyến khích bắt đầu từ một thay đổi nhỏ có thể duy trì, theo dõi điều gì thuận lợi và điều gì gây khó khăn, sau đó điều chỉnh. Người đọc có thể chia sẻ kinh nghiệm như một tình huống tham khảo thay vì công thức bắt buộc. Cách tiếp cận thực tế giúp giảm cảm giác tội lỗi và tạo điều kiện để thói quen tốt có thể được duy trì lâu hơn."}]','{"title":"Lối sống và tiêu dùng bền vững | Xanh Sky First","description":"Thay đổi thói quen bền vững bắt đầu bằng lựa chọn khả thi, không phải cảm giác hoàn hảo. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('tin-tuc-quy-chuan','Tiêu chuẩn biên tập và xác minh','published','[{"type":"heading","text":"Mỗi nội dung công khai cần được biên tập để rõ ràng, có nguồn và không gây hiểu nhầm."},{"type":"paragraph","text":"Trước khi xuất bản, người phụ trách cần kiểm tra tên riêng, ngày tháng, con số, địa điểm, nguồn ảnh và quyền sử dụng nội dung. Bài viết phải phân biệt thông tin đã xác nhận với kế hoạch đang dự kiến. Nếu thiếu dữ kiện quan trọng, nên chờ xác minh hoặc nêu rõ phần chưa chắc chắn thay vì lấp khoảng trống bằng suy đoán."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Nội dung có số liệu nên ghi nguồn, đơn vị, kỳ thống kê và phương pháp hiểu chỉ số. Ví dụ, lượt tham gia không giống số người duy nhất; khối lượng rác thu gom cần có cách ghi nhận và đơn vị phù hợp. Khi dùng lời kể hoặc trích dẫn, phải bảo đảm không làm thay đổi ý nghĩa và tôn trọng sự đồng ý của người liên quan."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi xuất bản, nếu phát hiện sai sót, nội dung nên được sửa kịp thời và có ghi nhận khi thay đổi ảnh hưởng đáng kể đến ý nghĩa. Người đọc cần có kênh gửi phản hồi. Quy trình này giúp website duy trì độ tin cậy và khuyến khích một văn hóa truyền thông coi trọng tính chính xác hơn là tốc độ hoặc sự chú ý tức thời."}]','{"title":"Tiêu chuẩn biên tập và xác minh | Xanh Sky First","description":"Mỗi nội dung công khai cần được biên tập để rõ ràng, có nguồn và không gây hiểu nhầm. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('tham-gia-quy-trinh','Quy trình đăng ký và tiếp nhận','published','[{"type":"heading","text":"Biểu mẫu cần dễ hiểu, chỉ thu thập dữ liệu cần thiết và thông báo rõ kết quả gửi."},{"type":"paragraph","text":"Trước khi điền, hãy đọc tên biểu mẫu, mục đích tiếp nhận, điều kiện tham gia và thời hạn nếu có. Các trường bắt buộc phải được đánh dấu rõ, còn trường không bắt buộc cần được nhận biết dễ dàng. Nếu cần tải tài liệu, biểu mẫu nên giải thích loại tệp và mục đích sử dụng. Người dùng không nên phải cung cấp thông tin vượt quá yêu cầu thực tế của chương trình."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Khi gửi, hệ thống cần kiểm tra dữ liệu ở cả trình duyệt và máy chủ, hiển thị lỗi gần trường liên quan, chống gửi lặp và chỉ thông báo thành công sau khi dữ liệu đã được lưu. Khi có mã hồ sơ, mã cần dễ sao chép và lưu lại. Email xác nhận chỉ được gửi nếu dịch vụ được cấu hình; trường hợp gửi email lỗi không nên làm mất hồ sơ đã lưu thành công."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Thông tin đăng ký phải được giới hạn cho người có quyền xử lý và chỉ sử dụng theo mục đích đã thông báo. Người phụ trách nên cập nhật trạng thái theo quy trình thống nhất. Nếu cần bổ sung thông tin, hãy giải thích rõ phần cần bổ sung và kênh gửi an toàn. Cách tiếp nhận nhất quán giúp người đăng ký hiểu điều gì xảy ra sau khi gửi, đồng thời giảm khối lượng liên hệ lặp lại."}]','{"title":"Quy trình đăng ký và tiếp nhận | Xanh Sky First","description":"Biểu mẫu cần dễ hiểu, chỉ thu thập dữ liệu cần thiết và thông báo rõ kết quả gửi. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('tham-gia-cau-hoi','Câu hỏi thường gặp khi tham gia','published','[{"type":"heading","text":"Những câu trả lời rõ ràng giúp người mới quyết định có nên đăng ký và chuẩn bị như thế nào."},{"type":"paragraph","text":"Bạn có cần kinh nghiệm trước không? Điều này phụ thuộc vào từng cơ hội. Các hoạt động giới thiệu kiến thức hoặc nhiệm vụ cơ bản có thể mở cho người mới, trong khi một số phần việc cần chuyên môn hoặc đào tạo phù hợp. Trang đăng ký phải nêu yêu cầu cụ thể; không nên khẳng định mọi hoạt động đều phù hợp với tất cả mọi người."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Tham gia có mất phí hay cần tự chuẩn bị vật dụng không? Chỉ nên công bố câu trả lời khi chương trình đã xác nhận rõ điều kiện. Nếu có chi phí phát sinh, đơn vị tổ chức phải thông báo trước, không để người tham gia bất ngờ. Nếu chương trình thay đổi hoặc bị hoãn, thông tin liên hệ và phương án thông báo cần được nêu để người đăng ký biết cách xử lý."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Sau khi gửi form, bạn nên lưu mã tiếp nhận và theo dõi trạng thái qua đường dẫn tra cứu khi chức năng đó được hỗ trợ. Gửi hồ sơ không đồng nghĩa được chọn ngay; người phụ trách có thể cần thời gian xem xét hoặc đề nghị bổ sung. Nếu có câu hỏi chưa được trả lời, hãy dùng kênh liên hệ chính thức và chỉ gửi thông tin cá nhân cần thiết để giải quyết vấn đề."}]','{"title":"Câu hỏi thường gặp khi tham gia | Xanh Sky First","description":"Những câu trả lời rõ ràng giúp người mới quyết định có nên đăng ký và chuẩn bị như thế nào. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO pages(slug,title,status,blocks_json,seo_json,published_at,created_at,updated_at) VALUES ('tra-cuu-ma-ho-so','Mã hồ sơ và trạng thái xử lý','published','[{"type":"heading","text":"Mã hồ sơ giúp hệ thống tìm đúng lượt đăng ký mà không cần công khai toàn bộ thông tin cá nhân."},{"type":"paragraph","text":"Sau khi biểu mẫu được lưu thành công, hệ thống có thể cấp một mã hồ sơ riêng. Hãy sao chép chính xác mã này và giữ lại cho đến khi quy trình kết thúc. Không đăng mã công khai trên mạng xã hội nếu không cần thiết. Nếu mã được gửi qua email, hãy kiểm tra cả thư mục thư rác và địa chỉ email đã khai báo trong biểu mẫu."},{"type":"heading","text":"Điều cần lưu ý"},{"type":"paragraph","text":"Các trạng thái cần thể hiện tiến trình xử lý chứ không phải lời hứa về kết quả. “Đã tiếp nhận” cho biết hồ sơ đã được ghi nhận; “đang xem xét” nghĩa là người phụ trách đang xử lý; “cần bổ sung” chỉ ra người gửi cần thực hiện bước tiếp theo; “đã duyệt” hoặc “đã hoàn tất” chỉ xuất hiện khi đã có quyết định tương ứng. Website nên giải thích trạng thái bằng ngôn ngữ dễ hiểu."},{"type":"heading","text":"Cách áp dụng"},{"type":"paragraph","text":"Nếu không tra cứu được, hãy kiểm tra lại mã và thử sau một khoảng thời gian ngắn nếu hồ sơ vừa gửi. Nếu lỗi tiếp diễn, liên hệ hỗ trợ bằng kênh chính thức và cung cấp mã cần thiết, không gửi mật khẩu hoặc mã xác thực. Hệ thống chỉ nên trả về thông tin tối thiểu để xác nhận hồ sơ, còn câu trả lời chi tiết và tệp đính kèm phải được bảo vệ."}]','{"title":"Mã hồ sơ và trạng thái xử lý | Xanh Sky First","description":"Mã hồ sơ giúp hệ thống tìm đúng lượt đăng ký mà không cần công khai toàn bộ thông tin cá nhân. — nội dung hướng dẫn và thông tin của Xanh Sky First."}',datetime('now'),datetime('now'),datetime('now'));
